// @matrix 64x128
// @knobs Speed=0.2..3, Height=0.2..0.95, Bands=2..12, PixelScale=8..32
// Patternflow layer-stack composition — flattened by Pattern Lab.
// Layers (bottom → top):
//   1. Pixel 1 (pixel, normal, 100%)
//   2. Code 1 (code, normal, 100%)
const __W = 64, __H = 128;
const __stack = [];

function __b64(s, n) {
  const A = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  const out = new Uint8ClampedArray(n);
  let o = 0, buf = 0, bits = 0;
  for (let i = 0; i < s.length && o < n; i++) {
    const v = A.indexOf(s[i]);
    if (v < 0) continue;
    buf = (buf << 6) | v; bits += 6;
    if (bits >= 8) { bits -= 8; out[o++] = (buf >> bits) & 255; }
  }
  return out;
}

function __mkDisplay(L) {
  return {
    width: __W, height: __H,
    setPixel(x, y, r, g, b) {
      const xi = x | 0, yi = y | 0;
      if (xi < 0 || xi >= __W || yi < 0 || yi >= __H) return;
      const i = (yi * __W + xi) * 4, B = L.buf;
      if (Array.isArray(r)) { B[i] = r[0] || 0; B[i + 1] = r[1] || 0; B[i + 2] = r[2] || 0; }
      else { B[i] = r; B[i + 1] = g || 0; B[i + 2] = b || 0; }
      B[i + 3] = 255;
    },
    setValue(x, y, v) {
      const xi = x | 0, yi = y | 0;
      if (xi < 0 || xi >= __W || yi < 0 || yi >= __H) return;
      v = Number.isFinite(v) ? (v < 0 ? 0 : v > 1 ? 1 : v) : 0;
      const i = (yi * __W + xi) * 4, B = L.buf, T = L.lut;
      if (T) {
        const li = Math.round(v * 255) * 4;
        B[i] = T[li]; B[i + 1] = T[li + 1]; B[i + 2] = T[li + 2]; B[i + 3] = T[li + 3];
      } else {
        const byte = Math.round(v * 255);
        B[i] = byte; B[i + 1] = byte; B[i + 2] = byte; B[i + 3] = 255;
      }
    },
  };
}

// ── pixel layer: Pixel 1 ──
__stack.push({
  kind: "pixel", opacity: 1, blend: "normal", role: "paint", maskInvert: false,
  buf: __b64("", __W * __H * 4),
});

// ── code layer: Code 1 ──
(function () {
  // Shadow the wrapper's own exports: a layer that defines no setup/update
  // must yield undefined here, not capture the OUTER setup (infinite loop).
  var setup, update, draw;



function setup(params) {
  params.speed = 1.0;
  params.height = 0.55;
  params.bands = 4;
  params.pixelScale = 16; // 기본 16블록 픽셀화
  params.t = 0;
}

function update(dt, input, params) {
  if (input && input.knobValues) {
    params.speed = input.knobValues[0];
    params.height = input.knobValues[1];
    params.bands = Math.floor(input.knobValues[2]);
    params.pixelScale = Math.floor(input.knobValues[3]);
  }
  params.t += dt * params.speed;
}

function draw(display, params, time) {
  const w = display.width;
  const h = display.height;
  const t = params.t;
  const bands = Math.max(2, params.bands);

  const minV = 0.18;
  const foamWidth = 0.12; // 0.12로 선명하게 고정

  // --- 해안선 대각선 기울기 (반시계방향 30도) ---
  const tiltDeg = 30;
  const tiltRad = (tiltDeg * Math.PI) / 180;
  const aspectTilt = Math.tan(tiltRad) * (w / h);

  for (let y = 0; y < h; y++) {
    const ny = y / h;

    for (let x = 0; x < w; x++) {
      const nx = x / w;

      // Knob 4 (PixelScale) 기반 레트로 픽셀 도트 단위화
      const grid = Math.max(4, params.pixelScale);
      let pixelX = Math.floor(nx * grid) / grid;

      // 반시계방향 해안선 기울기 연산
      let shoreTilt = -aspectTilt * (pixelX - 0.5);

      let shoreY =
        0.08 +
        params.height * 0.82 +
        Math.sin(pixelX * Math.PI * 3.0 + Math.floor(t * 2.0) * 0.2) * 0.04 +
        shoreTilt;

      // 바다 경계선 아래 영역은 0.0 처리
      if (ny > shoreY) {
        display.setValue(x, y, 0.0);
        continue;
      }

      let depthRatio = ny / shoreY;

      let wavePattern = Math.sin(
        depthRatio * 12.0 - t * 3.5 + Math.sin(pixelX * 8.0)
      );

      let rawV = minV + depthRatio * 0.45 + wavePattern * 0.12;
      rawV = Math.max(minV, Math.min(0.85, rawV));

      let normalized = (rawV - minV) / (0.85 - minV);
      let qStep = Math.floor(normalized * bands) / (bands - 1);
      let v = minV + qStep * 0.67;

      // 고정된 0.12 두께의 거품 백파
      if (Math.abs(wavePattern - 0.75) < foamWidth) {
        v = 1.0;
      }

      // 해안선 소프트 페이드
      if (ny > shoreY - 0.02) {
        let fade = (shoreY - ny) / 0.02;
        v *= Math.max(0.0, fade);
      }

      display.setValue(x, y, Math.max(0.0, Math.min(1.0, v)));
    }
  }
}
  __stack.push({
    kind: "code", opacity: 1, blend: "normal", recolor: false, role: "paint", maskInvert: false,
    lut: [0,0,0,0,48,48,48,48,95,95,95,95,143,143,143,143,190,190,190,190,238,238,238,238,250,253,255,255,242,249,255,255,235,246,255,255,227,243,254,255,220,239,254,255,212,236,254,255,205,233,254,255,197,229,254,255,190,226,254,255,182,223,254,255,174,219,253,255,167,216,253,255,159,213,253,255,152,209,253,255,144,206,253,255,137,203,253,255,130,199,253,255,122,196,252,255,115,193,252,255,107,190,252,255,100,186,252,255,92,183,252,255,85,180,252,255,77,176,252,255,70,173,251,255,63,170,251,255,55,167,251,255,48,163,251,255,41,160,251,255,33,157,251,255,26,153,251,255,19,150,250,255,11,147,250,255,4,144,250,255,0,142,250,255,0,142,250,255,0,141,250,255,0,141,251,255,0,141,251,255,0,140,251,255,0,140,251,255,0,140,251,255,0,139,251,255,0,139,252,255,0,139,252,255,0,138,252,255,0,138,252,255,0,138,252,255,0,137,252,255,0,137,253,255,0,137,253,255,0,136,253,255,0,136,253,255,0,136,253,255,0,135,253,255,0,135,253,255,0,135,254,255,0,134,254,255,0,134,254,255,0,134,254,255,0,133,254,255,0,133,254,255,0,133,255,255,0,132,255,255,0,132,255,255,2,133,255,255,4,134,255,255,7,135,255,255,10,136,255,255,13,137,255,255,15,138,255,255,18,139,255,255,21,140,255,255,24,141,255,255,26,143,255,255,29,144,255,255,32,145,255,255,34,146,255,255,37,147,255,255,40,148,255,255,43,149,255,255,45,150,255,255,48,152,255,255,51,153,255,255,54,154,255,255,56,155,255,255,59,156,255,255,62,158,255,255,64,159,255,255,67,160,255,255,70,161,255,255,73,162,255,255,75,164,255,255,78,165,255,255,81,166,255,255,84,167,255,255,86,168,255,255,89,170,255,255,92,171,255,255,94,172,255,255,97,173,255,255,100,175,255,255,103,176,255,255,105,177,255,255,108,178,255,255,111,180,255,255,114,181,255,255,116,182,255,255,119,184,255,255,122,185,255,255,124,186,255,255,127,188,255,255,130,189,255,255,133,190,255,255,135,192,255,255,138,193,255,255,141,194,255,255,144,196,255,255,146,197,255,255,149,198,255,255,152,200,255,255,154,201,255,255,157,202,255,255,160,204,255,255,163,205,255,255,165,206,255,255,168,208,255,255,171,209,255,255,174,211,255,255,176,212,255,255,179,214,255,255,182,215,255,255,185,216,255,255,187,218,255,255,190,219,255,255,193,221,255,255,195,222,255,255,198,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255,199,224,255,255],
    buf: new Uint8ClampedArray(__W * __H * 4),
    params: {},
    fSetup: typeof setup === "function" ? setup : null,
    fUpdate: typeof update === "function" ? update : null,
    fDraw: typeof draw === "function" ? draw : null,
  });
})();

// Mask grouping: a mask layer paints nothing — it gates the nearest paint
// layer BELOW it (stacked masks intersect). Binary threshold: pixel-art masks
// switch on where alpha >= 0.5, code masks where luminance × alpha >= 0.5.
const __groups = [];
{
  let last = null;
  for (const L of __stack) {
    if (L.role === "mask") { if (last) last.masks.push(L); continue; }
    L.masks = [];
    last = L;
    if (L.opacity > 0) __groups.push(L);
  }
}

function __maskOn(M, j) {
  const B = M.buf;
  let on;
  if (M.kind === "pixel") on = B[j + 3] >= 128;
  else on = (0.2126 * B[j] + 0.7152 * B[j + 1] + 0.0722 * B[j + 2]) * (B[j + 3] / 255) >= 127.5;
  return M.maskInvert ? !on : on;
}

// One shared knob set: every layer receives the same input, exactly like
// patterns running on the device's four physical encoders.
function __mirror(L) {
  const inp = L.lastInput;
  if (!inp) return;
  L.params.knobValues = inp.knobValues;
  L.params.knobNormalized = inp.knobNormalized;
  L.params.knobDeltas = inp.knobDeltas;
  L.params.knobRanges = inp.knobRanges;
  L.params.btnPressed = inp.btnPressed;
  L.params.btnHeld = inp.btnHeld;
}

export function setup(params) {
  for (const L of __stack) {
    if (L.kind !== "code") continue;
    L.display = __mkDisplay(L);
    if (L.fSetup) L.fSetup(L.params);
  }
}

export function update(dt, input, params) {
  for (const L of __stack) {
    if (L.kind !== "code") continue;
    L.lastInput = input;
    __mirror(L);
    if (L.fUpdate) L.fUpdate(dt, input, L.params);
  }
}

export function draw(display, params, time) {
  for (const L of __stack) {
    if (L.kind !== "code" || !L.fDraw) continue;
    L.buf.fill(0);
    __mirror(L);
    L.fDraw(L.display, L.params, time);
    if (L.recolor && L.lut) {
      const B = L.buf, T = L.lut;
      for (let i = 0; i < B.length; i += 4) {
        if (B[i + 3] === 0) continue;
        const lum = Math.round(0.2126 * B[i] + 0.7152 * B[i + 1] + 0.0722 * B[i + 2]) * 4;
        B[i] = T[lum]; B[i + 1] = T[lum + 1]; B[i + 2] = T[lum + 2]; B[i + 3] = T[lum + 3];
      }
    }
  }

  // Composite bottom → top over the panel's opaque black.
  const count = __W * __H;
  for (let i = 0; i < count; i++) {
    const j = i * 4;
    let r = 0, g = 0, b = 0;
    for (const L of __groups) {
      let hidden = false;
      for (let m = 0; m < L.masks.length; m++) {
        if (!__maskOn(L.masks[m], j)) { hidden = true; break; }
      }
      if (hidden) continue;
      const B = L.buf;
      const a = (B[j + 3] / 255) * L.opacity;
      if (a <= 0) continue;
      const sr = B[j], sg = B[j + 1], sb = B[j + 2], inv = 1 - a;
      if (L.blend === "add") { r += sr * a; g += sg * a; b += sb * a; }
      else if (L.blend === "multiply") {
        r = r * inv + ((r * sr) / 255) * a;
        g = g * inv + ((g * sg) / 255) * a;
        b = b * inv + ((b * sb) / 255) * a;
      } else if (L.blend === "screen") {
        r = r * inv + (255 - ((255 - r) * (255 - sr)) / 255) * a;
        g = g * inv + (255 - ((255 - g) * (255 - sg)) / 255) * a;
        b = b * inv + (255 - ((255 - b) * (255 - sb)) / 255) * a;
      } else {
        r = r * inv + sr * a;
        g = g * inv + sg * a;
        b = b * inv + sb * a;
      }
    }
    display.setPixel(i % __W, (i / __W) | 0, r, g, b);
  }
}

